a.algorithm_id,
a.config_name,
a.status,
a.if_del,
a.if_show,
a.pic_url,
a.apply_module,
a.create_time,
a.update_time
from t_algorithm_conf_bak a
where 1 = 1
 and a.device_mete_id = #{deviceMeteId, jdbcType=BIGINT}
